Customer Portal.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Customer Portal container

System_Ext(AzureAPIManagement, "Azure API Management", "Azure API Management", "Routes HTTPS traffic for online claims")
System_Ext(AzureAppConfiguration, "Azure App Configuration", "Azure App Configuration SDK", "Fetches dynamic feature toggles and configuration settings")

Container_Boundary(CustomerPortal, "Customer Portal") {
    Component(ClaimSubmissionUI, "Claim Submission UI", "React / TypeScript", "Provides responsive user interface components for customers and brokers to submit and track online claims.")
    Component(FeatureFlagClient, "Feature Flag Client", "Azure App Configuration SDK", "Fetches dynamic feature toggles and configuration settings to control UI behavior at runtime.")
}

Rel(ClaimSubmissionUI, AzureAPIManagement, "Routes HTTPS traffic for online claims", "HTTPS / TLS 1.3")
Rel(FeatureFlagClient, AzureAppConfiguration, "Fetches dynamic feature toggles", "HTTPS")

@enduml
